import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";

// MATHEUS (fisioterapeuta particular, quiropraxia, atende em casa). Anúncio QUADRADO 1080×1080, sempre 1:1.
// Roteiro do próprio cliente ((arquivo do cliente)), voz ElevenLabs "o locutor" (public/math/voz-v1.mp3, 32,0 s).
// Os tempos em C são os da locução (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada), medidos na transcrição.
// Sem logo: a identidade vem da foto de perfil dele — azul-marinho, aro azul vivo, coluna em linha azul, sem serifa.
// Tom sério e acolhedor. O problema (0–15 s) é todo desenhado; os vídeos dele entram quando a fala apresenta o tratamento.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos, nos vídeos e na câmera.

const { fontFamily: FONT } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const MATH_FPS = 30;
const FPS = MATH_FPS;
const LEAD = 0.3;

// tempos da fala
const C = {
  voce: 0.41, travado: 1.25, sente: 2.63, coluna: 2.95, fim: 3.55,
  toma: 4.93, melhora: 6.19, outro: 7.78, dor: 8.98,
  dor2: 10.24, todo: 11.1, nao: 11.92, e2: 13.38, rotina: 14.4,
  meu: 15.35, matheus: 15.67, sou: 16.51, espec: 17.43,
  eu: 19.5, trat: 19.92, so: 20.62,
  q1: 21.62, rpg: 22.74, pil: 23.58, dry: 24.72, lib: 25.52,
  atendo: 27.18, resid: 28.02,
  clique: 28.93, fale: 29.39, agende: 30.39, consulta: 31.23, fim2: 32.01,
};
// trocas de cena
const T2 = C.sente - 0.22, T3 = C.toma - 0.25, T4 = C.dor2 - 0.28, T5 = C.meu - 0.2, T6 = C.eu - 0.2;
const T7 = C.q1 - 0.18, T8 = C.atendo - 0.22, T9 = C.clique - 0.2;
const END = C.fim2 + 0.25;                      // cartão final
export const MATH_FRAMES = Math.round((END + 2.3 + LEAD) * FPS);
const F = (s: number) => Math.round((s + LEAD) * FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const shake = (t: number, a: number, d = 0.5, amp = 14) => (t < a || t > a + d ? 0 : Math.sin((t - a) * 46) * amp * (1 - (t - a) / d));

const BG = "#0E2A47";                           // azul-marinho da foto
const CARD = "#163A60";
const EDGE = "#24527F";
const BLUE = "#2F8FFF";                         // aro da foto
const SKY = "#8CCBFF";
const WHITE = "#FFFFFF";
const DIM = "rgba(255,255,255,0.62)";
const RED = "#FF5B5F";                          // só a dor, só no trecho do problema
const COL = 840;                                // coluna central (margem de 120)

const mix = (a: string, b: string, p: number) => {
  const q = Math.max(0, Math.min(1, p));
  const h = (s: string, i: number) => parseInt(s.slice(1 + 2 * i, 3 + 2 * i), 16);
  return `rgb(${[0, 1, 2].map((i) => Math.round(h(a, i) + (h(b, i) - h(a, i)) * q)).join(",")})`;
};

// texto: entra com opacidade e escala, sem deslocar, e fica parado; sai apagando no mesmo lugar
const tin = (t: number, at: number, out?: number, d = 0.36): React.CSSProperties => {
  const e = pop(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return { opacity: Math.min(1, lin(t, at, at + 0.12) * 1.2) * (1 - o), transform: `scale(${(0.8 + 0.2 * e).toFixed(4)})` };
};
type L = [React.ReactNode, number, number?, string?];  // texto, entrada, tamanho, cor
const Title: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number }> = ({ t, items, size, top, color = WHITE, out }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.08 }}>
    {items.map(([w, at, sz, c], i) => (
      <div key={i} style={{ fontFamily: FONT, fontWeight: 800, fontSize: sz ?? size, lineHeight: 1.08, letterSpacing: "-0.02em", whiteSpace: "nowrap", color: c ?? color, ...tin(t, at, out) }}>{w}</div>
    ))}
  </div>
);
// frases que se revezam no mesmo lugar: a anterior some inteira antes de a próxima entrar
const Swap: React.FC<{ t: number; top: number; items: L[]; size: number }> = ({ t, top, items, size }) => (
  <>
    {items.map(([w, at, sz, c], i) => {
      const next = items[i + 1]?.[1];
      if (t < at - 0.01 || (next !== undefined && t > next)) return null;
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center" }}>
          <div style={{ fontFamily: FONT, fontWeight: 800, fontSize: sz ?? size, lineHeight: 1.08, letterSpacing: "-0.02em", whiteSpace: "nowrap", color: c ?? WHITE, ...tin(t, at, next === undefined ? undefined : next - 0.18) }}>{w}</div>
        </div>
      );
    })}
  </>
);
const Caps: React.FC<{ children: React.ReactNode; size?: number; color?: string; style?: React.CSSProperties }> = ({ children, size = 28, color = DIM, style }) => (
  <div style={{ fontFamily: FONT, fontWeight: 600, fontSize: size, letterSpacing: "0.22em", textTransform: "uppercase", color, whiteSpace: "nowrap", ...style }}>{children}</div>
);
const S: React.FC<{ children: React.ReactNode }> = ({ children }) => <span style={{ color: SKY }}>{children}</span>;
const Cam: React.FC<{ s: number; x?: number; y?: number; origin?: string; children: React.ReactNode }> = ({ s, x = 0, y = 0, origin = "50% 50%", children }) => (
  <div style={{ position: "absolute", inset: 0, transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${s.toFixed(4)})`, transformOrigin: origin }}>{children}</div>
);

// ───────── 1 · acorda travado (desenho) ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const hot = k(t, C.travado, 0.3);
  const arm = k(t, C.travado - 0.05, 0.35);
  const ring = t < C.travado;
  const rot = ring ? Math.sin(t * 52) * 11 : 0;
  const pulse = 0.7 + 0.3 * Math.sin(t * 8);
  const cam = 1 + 0.13 * io(t, -LEAD, T2 + 0.2) + 0.04 * bump(t, C.travado, 0.45);
  // braço: do joelho para a lombar
  const ex = 360 + (505 - 360) * arm, ey = 665 + (640 - 665) * arm;
  const hx = 318 + (452 - 318) * arm, hy = 742 + (706 - 742) * arm;
  const fig = Math.min(1, pop(t, -LEAD + 0.05, 0.35) * 2);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Title t={t} top={92} size={68} items={[["Você que acorda", C.voce]]} />
      <Title t={t} top={176} size={124} items={[["TRAVADO", C.travado, undefined, RED]]} />
      <Cam s={cam} x={shake(t, C.travado, 0.45, 16)} origin="45% 72%">
        <svg width={1080} height={1080} viewBox="0 0 1080 1080" style={{ position: "absolute", inset: 0, opacity: fig }}>
          <defs>
            <radialGradient id="m1hot"><stop offset="0" stopColor={RED} stopOpacity={0.55} /><stop offset="1" stopColor={RED} stopOpacity={0} /></radialGradient>
          </defs>
          <line x1={150} y1={944} x2={930} y2={944} stroke={EDGE} strokeWidth={8} strokeLinecap="round" />
          {/* cama */}
          <rect x={380} y={762} width={420} height={62} rx={22} fill={CARD} stroke={EDGE} strokeWidth={6} />
          <rect x={700} y={724} width={88} height={40} rx={18} fill={EDGE} />
          <rect x={782} y={640} width={26} height={304} rx={10} fill={EDGE} />
          <rect x={396} y={824} width={20} height={120} rx={8} fill={EDGE} />
          {/* criado-mudo e despertador */}
          <rect x={830} y={820} width={110} height={124} rx={14} fill={CARD} stroke={EDGE} strokeWidth={6} />
          <g transform={`translate(885 752) rotate(${rot.toFixed(2)})`}>
            <circle cx={-34} cy={-44} r={16} fill={SKY} />
            <circle cx={34} cy={-44} r={16} fill={SKY} />
            <circle cx={0} cy={0} r={52} fill={BG} stroke={SKY} strokeWidth={9} />
            <line x1={0} y1={0} x2={0} y2={-30} stroke={WHITE} strokeWidth={7} strokeLinecap="round" />
            <line x1={0} y1={0} x2={22} y2={10} stroke={WHITE} strokeWidth={7} strokeLinecap="round" />
            <line x1={-30} y1={48} x2={-38} y2={62} stroke={SKY} strokeWidth={8} strokeLinecap="round" />
            <line x1={30} y1={48} x2={38} y2={62} stroke={SKY} strokeWidth={8} strokeLinecap="round" />
          </g>
          {ring && [0, 1].map((i) => (
            <path key={i} d={i ? "M958 700 q20 30 0 64" : "M812 700 q-20 30 0 64"} fill="none" stroke={SKY} strokeWidth={6} strokeLinecap="round" opacity={0.4 + 0.6 * Math.abs(Math.sin(t * 14 + i))} />
          ))}
          {/* dor na lombar */}
          <circle cx={448} cy={690} r={130} fill="url(#m1hot)" opacity={hot * pulse} />
          {/* pessoa sentada na beira da cama, de lado */}
          <g stroke={SKY} strokeWidth={30} strokeLinecap="round" strokeLinejoin="round" fill="none">
            <path d="M436 748 L300 758 L292 930" />
            <path d={`M436 748 Q 438 650 ${404 - 8 * hot} 566`} />
            <path d={`M410 584 L${ex.toFixed(1)} ${ey.toFixed(1)} L${hx.toFixed(1)} ${hy.toFixed(1)}`} />
          </g>
          <circle cx={384 - 10 * hot} cy={506 + 6 * hot} r={52} fill={SKY} />
          {/* riscos de dor */}
          {[0, 1, 2].map((i) => {
            const a = -0.9 + i * 0.6, p = k(t, C.travado + 0.08 + i * 0.05, 0.25);
            return <line key={i} x1={448 + Math.cos(a) * 92} y1={690 + Math.sin(a) * 92} x2={448 + Math.cos(a) * (92 + 46 * p)} y2={690 + Math.sin(a) * (92 + 46 * p)} stroke={RED} strokeWidth={10} strokeLinecap="round" opacity={p} />;
          })}
        </svg>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── 2 · a coluna no fim do dia (desenho) ─────────
const N_V = 11;
const Spine: React.FC<{ heat: (i: number) => number; y0: number; step: number }> = ({ heat, y0, step }) => (
  <svg width={1080} height={1080} viewBox="0 0 1080 1080" style={{ position: "absolute", inset: 0 }}>
    {Array.from({ length: N_V }).map((_, i) => {
      const w = 92 + i * 9, cx = 540 + 24 * Math.sin((i / (N_V - 1)) * Math.PI * 1.6 - 0.5), y = y0 + i * step;
      const h = heat(i);
      return (
        <g key={i}>
          {i >= N_V - 3 && h > 0.4 && <ellipse cx={cx} cy={y + 20} rx={w * 1.05} ry={44} fill={RED} opacity={0.16 * h} />}
          <rect x={cx - w / 2 - 26} y={y + 12} width={30} height={16} rx={8} fill={mix(EDGE, RED, h)} />
          <rect x={cx + w / 2 - 4} y={y + 12} width={30} height={16} rx={8} fill={mix(EDGE, RED, h)} />
          <rect x={cx - w / 2} y={y} width={w} height={40} rx={14} fill={mix(CARD, RED, h * 0.85)} stroke={mix(SKY, RED, h)} strokeWidth={6} />
          {i < N_V - 1 && <rect x={cx - w * 0.32} y={y + 42} width={w * 0.64} height={step - 44} rx={4} fill={SKY} opacity={0.35} />}
        </g>
      );
    })}
  </svg>
);
const S2: React.FC<{ t: number }> = ({ t }) => {
  const heat = (i: number) => 0.92 * k(t, C.coluna + (N_V - 1 - i) * 0.1, 0.3) + 0.08 * bump(t, C.fim, 0.5);
  const cam = 1 + 0.07 * io(t, T2, T3 + 0.2);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Title t={t} top={88} size={70} items={[["Sente a coluna", C.sente], [<S key="s">no fim do dia</S>, C.fim]]} />
      <Cam s={cam} y={14 * io(t, T2, T3)} origin="50% 34%">
        <div style={{ position: "absolute", inset: 0, opacity: Math.min(1, k(t, T2, 0.3) * 1.5), transform: `scale(${(0.9 + 0.1 * pop(t, T2, 0.4)).toFixed(4)})`, transformOrigin: "50% 70%" }}>
          <Spine heat={heat} y0={340} step={54} />
        </div>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── 3 · remédio, melhora, a dor volta (desenho) ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const level = 0.84 - 0.44 * io(t, C.melhora, C.melhora + 0.9) + 0.55 * k(t, C.dor, 0.35);
  const lv = Math.min(0.97, level);
  const cam = 1 + 0.1 * io(t, T3, T4);
  const blister = t < C.outro + 0.1;
  const bOut = io(t, C.outro - 0.15, C.outro + 0.1);
  const flip = io(t, C.outro + 0.15, C.outro + 0.45);
  const calRed = k(t, C.dor, 0.3);
  const pill = k(t, C.melhora - 0.1, 0.5);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Swap t={t} top={110} size={72} items={[["Toma remédio", C.toma], ["Melhora um pouco…", C.melhora], ["No outro dia…", C.outro], ["A DOR VOLTA", C.dor, 104, RED]]} />
      <Cam s={cam} x={shake(t, C.dor, 0.5, 14)} origin="50% 60%">
        {/* cartela */}
        {blister && (
          <div style={{ position: "absolute", left: 330, top: 330, width: 420, height: 270, borderRadius: 34, background: CARD, border: `5px solid ${EDGE}`, boxSizing: "border-box", opacity: (1 - bOut) * Math.min(1, pop(t, C.toma - 0.05, 0.3) * 2), transform: `scale(${((0.75 + 0.25 * pop(t, C.toma - 0.05, 0.45)) * (1 - 0.2 * bOut)).toFixed(4)}) rotate(${(-6 + 6 * k(t, C.toma, 0.5)).toFixed(2)}deg)` }}>
            {Array.from({ length: 8 }).map((_, i) => {
              const gone = i === 2 && t >= C.melhora - 0.1;
              return <div key={i} style={{ position: "absolute", left: 38 + (i % 4) * 88, top: 46 + Math.floor(i / 4) * 102, width: 64, height: 76, borderRadius: 32, background: gone ? "transparent" : WHITE, border: `5px solid ${gone ? EDGE : "rgba(255,255,255,0.4)"}`, boxSizing: "border-box" }} />;
            })}
          </div>
        )}
        {blister && pill > 0 && pill < 1 && (
          <div style={{ position: "absolute", left: 506, top: 380 - 190 * pill, width: 64, height: 76, borderRadius: 32, background: WHITE, opacity: 1 - lin(pill, 0.6, 1), transform: `rotate(${(pill * 160).toFixed(1)}deg)` }} />
        )}
        {/* calendário */}
        {t > C.outro - 0.15 && (
          <div style={{ position: "absolute", left: 380, top: 300, width: 320, height: 330, borderRadius: 34, background: CARD, border: `5px solid ${mix(EDGE, RED, calRed)}`, boxSizing: "border-box", overflow: "hidden", opacity: bOut, transform: `scale(${(0.8 + 0.2 * pop(t, C.outro - 0.15, 0.45)).toFixed(4)})` }}>
            <div style={{ height: 86, background: mix(BLUE, RED, calRed) }} />
            <div style={{ position: "absolute", left: 0, right: 0, top: 126, textAlign: "center", fontFamily: FONT, fontWeight: 900, fontSize: 120, color: WHITE, transform: `scaleY(${Math.abs(1 - 2 * flip).toFixed(4)})` }}>{flip < 0.5 ? "SEG" : "TER"}</div>
          </div>
        )}
        {/* medidor de dor */}
        <div style={{ position: "absolute", left: 120, top: 720, width: COL, opacity: Math.min(1, k(t, T3 + 0.1, 0.3) * 1.5) }}>
          <Caps size={26}>Nível de dor</Caps>
          <div style={{ marginTop: 18, height: 60, borderRadius: 30, background: CARD, border: `4px solid ${EDGE}`, boxSizing: "border-box", overflow: "hidden" }}>
            <div style={{ width: `${(lv * 100).toFixed(2)}%`, height: "100%", borderRadius: 30, background: mix(SKY, RED, (lv - 0.4) / 0.45) }} />
          </div>
        </div>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── 4 · não é normal / não precisa virar rotina ─────────
const DAYS = ["D", "S", "T", "Q", "Q", "S", "S"];
const Week: React.FC<{ t: number; top: number; at: number; fix?: number }> = ({ t, top, at, fix }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", gap: 22 }}>
    {DAYS.map((d, i) => {
      const ok = fix === undefined ? 0 : k(t, fix + i * 0.09, 0.3);
      const c = mix(RED, BLUE, ok);
      return (
        <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: Math.min(1, pop(t, at + i * 0.07, 0.3) * 2), transform: `scale(${((0.6 + 0.4 * pop(t, at + i * 0.07, 0.35)) * (1 + 0.14 * bump(t, (fix ?? -9) + i * 0.09, 0.3))).toFixed(4)})` }}>
          <div style={{ width: 92, height: 92, borderRadius: "50%", background: c, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <svg width={44} height={44} viewBox="0 0 44 44" fill="none" stroke={WHITE} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round">
              {ok < 0.5 ? <path d="M10 10l24 24M34 10L10 34" /> : <path d="M8 23l10 10 18-21" />}
            </svg>
          </div>
          <Caps size={26} color={DIM} style={{ letterSpacing: "0.05em" }}>{d}</Caps>
        </div>
      );
    })}
  </div>
);
const S4: React.FC<{ t: number }> = ({ t }) => {
  const b = t >= C.nao - 0.04 && t < C.e2 - 0.12;
  const c = t >= C.e2 - 0.12;
  if (b) {
    const cam = 1 + 0.06 * lin(t, C.nao, C.e2);
    return (
      <AbsoluteFill style={{ background: BLUE, alignItems: "center", justifyContent: "center" }}>
        <div style={{ transform: `scale(${(cam * (0.55 + 0.45 * pop(t, C.nao - 0.04, 0.3))).toFixed(4)}) rotate(${(-4 + 4 * k(t, C.nao, 0.35)).toFixed(2)}deg)`, fontFamily: FONT, fontWeight: 900, fontSize: 176, lineHeight: 0.98, letterSpacing: "-0.03em", color: BG, textAlign: "center" }}>
          NÃO É<br />NORMAL
        </div>
      </AbsoluteFill>
    );
  }
  if (c) {
    return (
      <AbsoluteFill style={{ background: BG }}>
        <Title t={t} top={150} size={80} items={[["E não precisa", C.e2 - 0.05], [<S key="s">virar rotina</S>, C.rotina]]} />
        <Cam s={1 + 0.08 * io(t, C.e2, T5)} origin="50% 62%">
          <Week t={t} top={560} at={C.e2 - 0.4} fix={C.rotina + 0.15} />
        </Cam>
      </AbsoluteFill>
    );
  }
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Title t={t} top={250} size={96} items={[["Dor que volta", C.dor2 - 0.05], ["todo dia", C.todo, undefined, RED]]} />
      <Cam s={1 + 0.06 * io(t, T4, C.nao)} origin="50% 62%">
        <Week t={t} top={600} at={C.todo + 0.05} />
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── 5 · Matheus ─────────
const Photo: React.FC<{ size: number; zoom: number; glow?: number }> = ({ size, zoom, glow = 0.35 }) => (
  <div style={{ width: size, height: size, borderRadius: "50%", overflow: "hidden", boxShadow: `0 0 ${Math.round(size * 0.12)}px rgba(47,143,255,${glow})` }}>
    <Img src={staticFile("math/matheus.png")} style={{ width: size, height: size, transform: `scale(${zoom.toFixed(4)})`, transformOrigin: "62% 40%" }} />
  </div>
);
const S5: React.FC<{ t: number }> = ({ t }) => {
  const e = pop(t, T5 + 0.08, 0.5);
  return (
    <AbsoluteFill style={{ background: BG }}>
      {/* câmera em três tempos: chega, aproxima no "fisioterapeuta", aproxima de novo na quiropraxia */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 96, display: "flex", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${((0.7 + 0.3 * e) * (1 + 0.035 * k(t, C.sou, 0.6) + 0.035 * k(t, C.espec + 0.3, 0.6))).toFixed(4)}) rotate(${(-3 + 3 * k(t, T5 + 0.08, 0.7)).toFixed(2)}deg)`, transformOrigin: "50% 50%" }}>
        <Photo size={490} zoom={1 + 0.08 * k(t, C.matheus, 0.8) + 0.1 * k(t, C.sou, 0.9) + 0.08 * k(t, C.espec + 0.3, 0.9) + 0.03 * lin(t, T5, T6)} />
        <svg width={560} height={560} viewBox="0 0 560 560" style={{ position: "absolute", left: 260, top: -35 }} fill="none">
          <circle cx={280} cy={280} r={266} stroke={SKY} strokeWidth={6} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - k(t, C.matheus - 0.1, 0.8)} transform="rotate(-90 280 280)" opacity={0.8} />
        </svg>
      </div>
      <Title t={t} top={648} size={98} items={[["Matheus", C.matheus]]} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 778, display: "flex", justifyContent: "center", ...tin(t, C.sou + 0.1) }}>
        <Caps size={34} color={WHITE}>Fisioterapeuta</Caps>
      </div>
