// ───────── montagem: cada troca de cena de um jeito ─────────
export const MathFisio: React.FC = () => {
  const t = useCurrentFrame() / FPS - LEAD;
  const z2 = io(t, T2 - 0.18, T2 + 0.16);       // 1→2: atravessa aproximando
  const p3 = io(t, T3 - 0.2, T3 + 0.16);        // 2→3: a nova empurra de baixo
  const o4 = io(t, T4 - 0.3, T4 - 0.04);        // 3→4: círculo azul, depois a cena
  const p4 = io(t, T4 - 0.06, T4 + 0.28);
  const p5 = io(t, T5 - 0.2, T5 + 0.16);        // 4→5: abre do meio para os lados
  const p6 = io(t, T6 - 0.2, T6 + 0.18);        // 5→6: a nova entra pela direita
  const p7 = io(t, T7 - 0.2, T7 + 0.2);         // 6→7: faixa inclinada
  const p8 = io(t, T8 - 0.2, T8 + 0.18);        // 7→8: a nova desce de cima
  const p9 = io(t, T9 - 0.2, T9 + 0.18);        // 8→9: a nova entra pela esquerda
  const band = -30 + 160 * p7;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {t < T2 + 0.2 && <AbsoluteFill style={{ transform: `scale(${(1 + 0.6 * z2).toFixed(4)})`, opacity: 1 - z2 }}><S1 t={t} /></AbsoluteFill>}
      {z2 > 0 && t < T3 + 0.2 && <AbsoluteFill style={{ transform: `translateY(${(-28 * p3).toFixed(2)}%) scale(${(0.85 + 0.15 * z2).toFixed(4)})`, opacity: z2 }}><S2 t={t} /></AbsoluteFill>}
      {p3 > 0 && t < T4 + 0.3 && <AbsoluteFill style={{ transform: `translateY(${(100 - 100 * p3).toFixed(2)}%)` }}><S3 t={t} /></AbsoluteFill>}
      {o4 > 0 && t < T4 + 0.3 && <AbsoluteFill style={{ background: BLUE, clipPath: `circle(${(o4 * 75).toFixed(2)}% at 50% 50%)` }} />}
      {p4 > 0 && t < T5 + 0.2 && <AbsoluteFill style={{ clipPath: `circle(${(p4 * 75).toFixed(2)}% at 50% 50%)` }}><S4 t={t} /></AbsoluteFill>}
      {p5 > 0 && t < T6 + 0.2 && <AbsoluteFill style={{ clipPath: `inset(0 ${(50 - 50 * p5).toFixed(2)}% 0 ${(50 - 50 * p5).toFixed(2)}%)`, transform: `translateX(${(-100 * p6).toFixed(2)}%)` }}><S5 t={t} /></AbsoluteFill>}
      {p6 > 0 && t < T7 + 0.25 && <AbsoluteFill style={{ transform: `translateX(${(100 - 100 * p6).toFixed(2)}%)` }}><S6 t={t} /></AbsoluteFill>}
      {p7 > 0 && p7 < 1 && <AbsoluteFill style={{ background: BLUE, clipPath: `polygon(0 0, ${band + 12}% 0, ${band - 18}% 100%, 0 100%)` }} />}
      {p7 > 0 && t < T8 + 0.2 && <AbsoluteFill style={{ clipPath: `polygon(0 0, ${band}% 0, ${band - 30}% 100%, 0 100%)`, transform: `translateY(${(30 * p8).toFixed(2)}%)` }}><S7 t={t} /></AbsoluteFill>}
      {p8 > 0 && t < T9 + 0.2 && <AbsoluteFill style={{ transform: `translateY(${(-100 + 100 * p8).toFixed(2)}%) translateX(${(100 * p9).toFixed(2)}%)` }}><S8 t={t} /></AbsoluteFill>}
      {p9 > 0 && <AbsoluteFill style={{ transform: `translateX(${(-100 + 100 * p9).toFixed(2)}%)` }}><S9 t={t} /></AbsoluteFill>}
    </AbsoluteFill>
  );
};

